INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('5cbbfdcc-01ed-5deb-a69a-bcd2a5ac899a', 'BDS_PR46049848', 'APARTMENT', 'Căn hộ S-Light Tower Đà Nẵng 2 phòng ngủ view sông Hàn, giá full 2.8 tỉ, tầng cao', 'Căn hộ 2 phòng ngủ dự án S-Light Tower Đà Nẵng.
View sông Hàn, tầng cao.
Công năng 2 phòng ngủ, 1 nhà vệ sinh.
Diện tích 58m².
Bàn giao hoàn thiện trần tường sàn.
Đã khởi công xây dựng, dự kiến bàn giao tháng 6/2028.
Giá bán bao gồm VAT và phí bảo trì:
+ Thanh toán nhanh: 2.8 tỉ.
+ Thanh toán tiến độ: 3.2 tỉ.
+ Thanh toán vay: 3.3 tỉ.
Khách hàng thanh toán tiến độ chỉ cần thanh toán 70% nhận nhà, 30% còn lại thanh toán trong vòng 2 năm kể từ ngày nhận nhà.
Khách hàng thanh toán vay thanh toán 25% giá trị căn hộ, ngân hàng miễn lãi và ân hạn nợ trong vòng 24 tháng kể từ ngày giải ngân.
