INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('b86590a9-e63c-5eee-bd21-310cee02a9bb', 'BDS_PR46143983', 'APARTMENT', 'Chỉ với 1,1tỉ sở hữu ngay căn hộ hạng sang The Prive 2PN 81m2, MB hỗ trợ vay 60 tháng không gốc lãi', 'The Prive là căn hộ hạng sang có mức giá cực kỳ hợp lý nằm tại khu vực trung tâm Quận 2 cũ, được bàn giao nội thất sang trọng top đầu khu vực và cũng là dự án có phương thức thanh toán tốt nổi bật.

Em Đông còn vài căn suất nội bộ The Prive được cập nhật liên tục với mức giá cực kỳ ưu đãi như sau:
* Căn 1PN:
+ Căn 1PN diện tích 50m², giá chỉ 6 tỷ đã bao gồm VAT và PBT.
* Căn 2PN:
+ Căn 2PN diện tích 81m² giá chỉ 8,6 tỷ đã bao gồm VAT và PBT.
* Căn 3PN:
+ Căn 3PN diện tích 100m², giá chỉ 11,8 tỷ đã bao gồm VAT và PBT.

Hotline liên hệ: 0903 899 *** Mr Đông GDKD.

I, Về kết nối.
* The Prive là một trong những dự án thuộc đại đô thị Nam Rạch Chiếc, là nơi sở hữu vị trí vàng đắc địa của khu Đông TP. HCM khi chỉ:

+ 5 phút kết nối đến sân vận động Hoa Sen Nam Rạch Chiếc, 5 phút đi xe về Thảo Điền và 10p kết nối đến trung tâm Quận 1 cũ.

+ 10p để kết nối về đại đô thị Thủ Thiêm thông qua nút giao An Phú đang được hoàn thiện.

+ Trong bán kính 5km có thể kết nối với 06 cụm siêu thị và trung tâm thương mại, 08 trường quốc tế và 05 bệnh viện.

II, Về tiện ích.
* The Prive cũng là nơi phức hợp đầy đủ hơn 100 tiện ích nội ngoại khu, tiêu biểu như:

+ Đường chạy bộ và đường đi xe đạp ven sông lên đến 2km.

+ Sở hữu 03 cụm hồ bơi muối khoáng lên đến hơn 3000m².

+ Phòng tiệc theo phong cách Việt Nam, Nhật Bản, Trung Hoa.

+ Sở hữu cụm shophouse ven sông đẹp top đầu khu vực Quận 2.

* Ngoài ra e Đông cũng nắm giỏ hàng nội bộ khác thuộc The Prive như phân khu nhà 6,7,8,9,10,11.
+ Nhận booking cho tháp siêu sang 12 tối ưu khả năng chọn lựa căn đẹp theo mong muốn.

