INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('169a3796-71e9-5a7d-ad28-40d174f3d051', 'BDS_PR46144596', 'APARTMENT', 'Chỉ 2T7 Sở hữu ngay căn Penthouse S-Light Tower view Pháo Hoa Trung tâm Thành phố', 'S LIGHT TOWER: CĂN PENTHOUSE GÓC 2PN THÀNH DUPLEX 4PN CHỈ VỚI 2 TỶ7

Nằm ở tầng 22, chiều cao trần lên đến 7m
View trực diện sông Hàn, ôm trọn skyline Đà Nẵng và thưởng thức pháo hoa ngay tại phòng khách.
Bàn giao thô, chủ nhân tự do thiết kế theo phong cách riêng.
Số lượng căn đẹp có hạn

BÀI TOÁN ĐẦU TƯ SINH LỜI ĐÁNG CÂN NHẮC CHO NHỮNG CHỦ NHÂN TINH HOA
Chi phí đầu tư trên mỗi m² sử dụng thấp hơn so với việc mua một căn hộ lớn có diện tích tương đương.
Gia tăng giá trị tài sản sau khi hoàn thiện. Một căn duplex được thiết kế bài bản luôn có giá trị sử dụng và giá trị chuyển nhượng cao hơn so với căn hộ bàn giao thô ban đầu.
Nguồn cung cực kỳ khan hiếm. Toàn dự án chỉ có số lượng rất ít Penthouse góc, trong khi các sản phẩm sở hữu lâu dài, view sông - view pháo hoa tại Đà Nẵng ngày càng ít được phát triển.
Biên độ khai thác đa dạng. Có thể ở, làm second home, hoặc cho thuê khách chuyên gia, doanh nhân với phân khúc cao cấp - nhóm khách sẵn sàng trả mức thuê cao cho sản phẩm khác biệt.

Đặc biệt, chính sách mở bán cực hấp dẫn:
Chiết khấu không vay 3%
Thanh toán sớm, tổng ưu đãi từ 11% (chưa gồm Early Bird)
Hỗ trợ vay đến 70%
Ân hạn gốc & lãi 24 tháng
Sở hữu lâu dài
Một sản phẩm dành cho những khách hàng muốn sở hữu không gian sống đẳng cấp, khác biệt và khan hiếm tại trung tâm Đà Nẵng.
