INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('080a370c-1569-59e6-8d4f-523b13416275', 'BDS_PR46144516', 'APARTMENT', 'Sốc! Giá giảm khủng, căn 2N - 55m2, giá chỉ hơn 3 tỷ, sẵn sổ sang tên, sẵn dòng tiền 8tr/1 tháng', 'Căn hộ 2PN ban công hướng Đông Bắc, view đẹp, full đồ sẵn dòng tiền cho thuê 8tr/1 tháng, xứng đáng để xuống tiền ở và đầu tư dài hạn. Liên hệ: 0869 929 ***.
Thông tin căn hộ:

- Diện tích: 55m².
- Thiết kế: 2 phòng ngủ, 1 vệ sinh.
- Ban công hướng Đông Bắc, view thoáng đẹp, không bị chắn, đón gió và ánh sáng tự nhiên.
- Full nội thất như hình, chỉ cần xách vali vào ở.
Sổ đỏ sẵn, sang tên nhanh, pháp lý minh bạch.

Giá bán: 3,1 tỷ (thu về).

Ưu điểm nổi bật: Liên hệ: 0869 929 ***.
- Căn hộ đã có sẵn khách thuê, dòng tiền ổn định 8 triệu/tháng.
- View thoáng, không gian sống mát mẻ, nhiều ánh sáng.
- Nội thất đầy đủ, tiết kiệm chi phí hoàn thiện.
- Phù hợp cả nhu cầu an cư và đầu tư giữ tài sản lâu dài.
- Chủ nhà hợp tác, sẵn pass xem nhà bất cứ lúc nào.

Căn đẹp pháp lý rõ ràng giá tốt luôn được giao dịch rất nhanh. Đừng bỏ lỡ cơ hội sở hữu căn hộ chất lượng với mức giá cạnh tranh.

Miễn phí môi giới 100%.

Liên hệ: 0869 929 *** ngay để xem nhà 24/7.', 'AVAILABLE', 'The Sapphire 1 - Vinhomes Ocean Park, Xã Đa Tốn, Huyện Gia Lâm, Hà Nội', 'Xã Đa Tốn', 'Huyện Gia Lâm', 'Hà Nội', 20.995746, 105.944082, 55.00, NULL, 2, 1, NULL, NULL, 'Sổ đỏ/ Sổ hồng', 3100000000.00, 'VND', NULL, NULL, NULL, NULL, NULL, NULL, '{"balcony_orientation":"Đông Bắc","commercial_subtype":null,"content_sha256":"588b1f02ecdb11b051d0b50cfef4dbf46435fc8b355e8e5fcdc9f657aff3a1b6","crawled_at":"2026-08-06T07:05:21.459056Z","furniture_status":"Đầy đủ","last_seen_at":"2026-08-06T07:05:21.459056Z","listing_type":"SALE","market_insights":{"annual_change_direction":"UP","annual_change_percent":7.1,"history_points":[],"pricing_history_endpoint":"https://batdongsan.com.vn/Origins/CommonData/GetPricingHistory","pricing_history_endpoint_available":true,"pricing_history_fetched":false,"pricing_history_years":1},"price_per_sqm":56363636,"price_period":"TOTAL","privacy":{"direct_contact_policy":"MASKED_PUBLIC_PHONE_ONLY","free_text_contact_redactions":0},"project":{"name":null,"url":null},"raw_attributes":[{"label":"Khoảng giá","normalized_key":"source_price_per_sqm","normalized_value":3100000000,"raw_value":"3,1 tỷ"},{"label":"Diện tích","normalized_key":"area_sqm","normalized_value":55.0,"raw_value":"55 m²"},{"label":"Số phòng ngủ","normalized_key":"bedrooms","normalized_value":2,"raw_value":"2 phòng"},{"label":"Số phòng tắm, vệ sinh","normalized_key":"bathrooms","normalized_value":1,"raw_value":"1 phòng"},{"label":"Hướng ban công","normalized_key":"balcony_orientation","normalized_value":"Đông Bắc","raw_value":"Đông - Bắc"},{"label":"Pháp lý","normalized_key":"legal_status","normalized_value":"Sổ đỏ/ Sổ hồng","raw_value":"Sổ đỏ/ Sổ hồng"},{"label":"Nội thất","normalized_key":"furniture_status","normalized_value":"Đầy đủ","raw_value":"Đầy đủ"}],"schema_version":"batdongsan-v1","seller":{"account_type":"UNKNOWN","active_listing_count":null,"avatar_url":"https://file4.batdongsan.com.vn/resize/200x200/2025/08/18/202