INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('b51bfe8f-f896-5559-9604-a9f1d1bd5d1c', 'BDS_PR46143953', 'APARTMENT', 'Chỉ cần 1 tỷ 073 triệu (10%) sở hữu căn 2PN Lumière Cao Xà Lá giá tốt hiếm có tại Nguyễn Trãi', 'Không cần bỏ ra đến 5 đến 7 tỷ ngay từ đầu, khách hàng hiện chỉ cần 1,073 tỷ (10%) là có thể sở hữu một căn 2PN tại dự án cao cấp khu vực Nguyễn Trãi do Masterise Homes phát triển.

* Thông tin căn hộ.
Loại hình: 2PN.
Diện tích thông thủy: 67,4m².
Hướng: Cửa Đông Nam - ban công Tây Bắc.
Thiết kế tối ưu:
Phòng khách rộng kết nối logia.
Phòng ngủ master riêng tư.
Phòng đa năng có thể làm phòng ngủ nhỏ, phòng làm việc hoặc phòng cho trẻ.
Phù hợp gia đình trẻ hoặc khách đầu tư cho thuê.

* Giá bán.
Giá thanh toán sớm: 10.331 tỷ - cuối năm nay mới cần thanh toán hết.
Giá tiến độ: 11.890 tỷ - tiến độ cực giãn.
Giá hỗ trợ lãi suất: 12.948 tỷ - CS vay HTLS 0% đến khi nhận nhà + HTLS cố định 7,5%/năm trong 2 năm - ân hạn gốc suốt thời gian HTLS.

* Dòng tiền ban đầu cực nhẹ.
Đặt cọc: 50 triệu.
Ký thỏa thuận: Khoảng 10%.
Tổng số tiền cần chuẩn bị giai đoạn đầu chỉ khoảng 1,07 tỷ đồng.

* Chính sách tài chính nổi bật.
- Thanh toán tiến độ giãn theo quý, khoảng 5%/quý.
- Vay tới 70%.
Hỗ trợ lãi suất 0% và ân hạn gốc đến Q2/2029.
Sau đó cố định lãi suất 7,5%/năm thêm 2 năm và tiếp tục ân hạn gốc đến Q2/2031.

* LUMIÈRE Hanoi Seasons Garden.
Vị trí 233 235 Nguyễn Trãi, đối diện Royal City.
Kết nối trực tiếp ga Metro Nguyễn Trãi.
10 tòa căn hộ cao cấp trên quỹ đất 11ha.
25 tiện ích ngoài trời, 8 tiện ích trong nhà.
Bể bơi 4 mùa, Clubhouse, Gym, Spa, Sky Garden.

* Chi tiết mặt bằng, bảng giá và phương án tài chính từng căn:
