INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('03ff7773-ba90-55f5-8eee-e516eac4e729', 'BDS_PR46076890', 'APARTMENT', 'Chính chủ bán căn 2PN tại tòa ĐN 1 KĐT Văn Khê, đường Tố Hữu, Hà Đông. Giá 3,95 tỷ', 'Gia đình cần bán căn hộ chung cư 59m² tại tòa Đơn Nguyên 1, Khu đô thị Văn Khê, quận Hà Đông, Hà Nội. Căn hộ có diện tích sử dụng hợp lý, phù hợp cho gia đình trẻ hoặc nhà đầu tư có nhu cầu cho thuê, dòng tiền đều đặn 8tr - 10tr/tháng.

Thông tin căn hộ:
- Diện tích: 59m².
- Thiết kế: 2 phòng ngủ, 1 phòng khách, bếp và khu vệ sinh.
- Pháp lý: Sổ đỏ cất két sẵn sàng giao dịch nhanh.
- Đầy đủ nội thất - khách mua có thể vào ở ngay:
Điều hòa - Giường ngủ - Tủ quần áo. Bàn ghế sofa - Tivi. Tủ bếp - Tủ lạnh - Máy giặt.
- Căn hộ nổi bật với thiết kế phong thủy tốt, mang lại cảm giác thoải mái và an lành cho cư dân. Khu vực sống yên tĩnh, gần gũi với thiên nhiên, phù hợp cho lối sống thư giãn và tiện lợi.

- Tiện ích xung quanh:
- Bệnh viện 103.
- Công viên Thiên Văn Học.
- Công viên An Hưng.
- Siêu thị Đức Thành.
- Khu vui chơi mua sắm AEON Mall.

Giá bán: 3 tỷ 950 triệu.

Hỗ trợ xem nhà:
- Các buổi tối từ thứ 2 đến thứ 6.
- Cả ngày thứ 7 và chủ nhật.
- Gia đình ưu tiên khách hàng có nhu cầu mua ở thực sự.
- Liên hệ chủ nhà: 0987 569 ***.', 'AVAILABLE', 'Khu đô thị Văn Khê, Đường Tố Hữu, Phường La Khê, Quận Hà Đông, Hà Nội', 'Phường La Khê', 'Quận Hà Đông', 'Hà Nội', 20.972347, 105.761475, 59.00, NULL, 2, 1, NULL, NULL, 'Sổ hồng sẵn sàng giao dịch', 3950000000.00, 'VND', NULL, NULL, NULL, NULL, NULL, NULL, '{"balcony_orientation":null,"commercial_subtype":null,"content_sha256":"0b46f82c382ea0e9f15ee96d0d91cb813f7273a7ec3800c62e90df345177e1b7","crawled_at":"2026-08-06T07:03:38.335480Z","furniture_status":"Full nội thất, khách chỉ cần xách valy về ở ngay sau khi ký cọc","last_seen_at":"2026-08-06T07:03:38.335480Z","listing_type":"SALE","market_insights":{"annual_change_direction":"UP","annual_change_percent":16.2,"history_points":[],"pricing_history_endpoint":"https://batdongsan.com.vn/Origins/CommonData/GetPricingHistory","pricing_history_endpoint_available":true,"pricing_history_fetched":false,"pricing_history_years":1},"price_per_sqm":66949152,"price_period":"TOTAL","privacy":{"direct_contact_policy":"MASKED_PUBLIC_PHONE_ONLY","free_text_contact_redactions":0},"project":{"name":null,"url":null},"raw_attributes":[{"label":"Khoảng giá","normalized_key":"source_price_per_sqm","normalized_value":3950000000,"raw_value":"3,95 tỷ"},{"label":"Diện tích","normalized_key":"area_sqm","normalized_value":59.0,"raw_value":"59 m²"},{"label":"Số phòng ngủ","normalized_key":"bedrooms","normalized_value":2,"raw_value":"2 phòng"},{"label":"Số phòng tắm, vệ sinh","normalized_key":"bathrooms","normalized_value":1,"raw_value":"1 phòng"},{"label":"Mức giá điện","normalized_key":null,"normalized_value":"Thỏa thuận","raw_value":"Thỏa thuận"},{"label":"Pháp lý","normalized_key":"legal_status","normalized_value":"Sổ hồng sẵn sàng giao dịch","raw_value":"Sổ hồng sẵn sàng giao dịch"},{"label":"Nội thất","normalized_key":"furniture_status","normalized_value":"Full nội thất, khách chỉ cần xách valy về ở ngay sau khi ký cọc","raw_value":"Full nội thất, khách chỉ cần xách valy về ở ngay sau khi ký c