INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('d0246741-b251-5f28-a2b0-1995c55b1df8', 'BDS_PR46000759', 'APARTMENT', 'Hiếm có khó tìm căn 2PN sổ đỏ cầm tay chỉ 3,65 tỷ, LH 0986 784 ***', 'Nếu bạn đang tìm một căn hộ 2PN vừa để ở, vừa giữ tài sản lâu dài, thì đây là lựa chọn rất đáng xem.

Mã căn: S1.11 tầng trên 10 căn số 10 quá đẹp.
Diện tích: 63,7m² thiết kế vuông vắn, tối ưu công năng.
Ban công Tây Bắc Đông Bắc, view thoáng, không bị chắn, đón gió và ánh sáng tự nhiên.
Full nội thất như hình chỉ cần xách vali vào ở.
Sổ đỏ cầm tay sang tên nhanh, giao dịch an tâm.
Giá chỉ 3,65 tỷ thu về mức giá rất cạnh tranh cho căn hộ đã có sổ và đầy đủ nội thất.
Xem nhà 24/7, sẵn pass, chủ hợp tác.
Không hỗ trợ vay ngân hàng.

Căn đẹp pháp lý rõ giá tốt luôn được khách chốt rất nhanh. Nếu bỏ lỡ hôm nay, rất có thể ngày mai căn hộ đã có chủ.

