INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('d3abf411-0161-539e-8e9c-2daf82fe65cb', 'BDS_PR46142547', 'HOUSE', 'Bán nhà Điện Biên Phủ Q.Bình Thạnh, Giá 3Tỷ860, 47m2, sổ chính chủ, dòng tiền cho thuê 22tr/tháng', 'Tôi cần bán gấp căn nhà đường Điện Biên Phủ Q.Bình Thạnh, gần ngã tư Hàng Xanh (nay thuộc phường Gia Định). Giá 3Tỷ860, đang cho thuê 22tr/tháng.
- Diện tích: 47,7m²
- Nhà có kết cấu: 1 Trệt 2 Lầu + Sân Thượng. Bên trong có 4 phòng ngủ, 4 nhà vệ sinh.
- Nhà tôi đang cho thuê với giá 22tr/ tháng
- Sổ hồng riêng chính chủ tên tôi.
- Hẻm trước nhà rộng 5m xe hơi đi thoải mái, hẻm cao ráo không ngập, hàng xóm thân thiện, khu vực yên tĩnh.
- Vị trí nhà thuận tiện di chuyển ra các quận trung tâm Quận 1, Quận 2, Quận 3, Phú Nhuận. Gần các Trường Đại Học Hồng Bàng, Hutech, Kinh Tế Tài Chính, khu du lịch Văn Thánh, Landmark 81
- Rất thích hợp mua để cho thuê, kinh doanh, làm tài sản cho con cháu
Tôi cần bán gấp trong tháng 8, anh chị thiện chí mua tôi có bơt.
