INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('866d1157-cfd6-5844-87de-9731baf47a0c', 'BDS_PR46142515', 'APARTMENT', 'Quỹ ẩn giá tốt bán căn 2PN, full nội thất, hiện đang vận hành 23tr/tháng, 2tr/ngày, The Gloria', 'Nhỉnh 8 tỷ - sở hữu ngay căn hộ 5* tại lõi phố cổ ngay Ba Đình, tặng kèm nội thất tiêu chuẩn khách sạn tại The Gloria By Silk Path.
- Sẵn sổ hồng lâu dài.
- Tầng đẹp - View trực diện Hồ Thành Công.
- Full nội thất cao cấp Chỉ việc xách vali vào ở.
- Sẵn hợp đồng thuê Tạo dòng tiền ngay khi nhận bàn giao.

Vị trí lõi trung tâm.
Số 8 Nguyên Hồng, P. Giảng Võ, Hà Nội. Đủ mọi tiện ích, thuận tiện di chuyển đến các khu văn phòng, trung tâm hành chính.

Công năng tối ưu.
Diện tích: 57 - 83 m².
Thiết kế 2 - 3 phòng ngủ; 2 phòng vệ sinh.
Phòng khách rộng, khu bếp tiện nghi.
100% phòng ngủ có cửa sổ đón ánh sáng và gió tự nhiên.

Trải nghiệm sống chuẩn khách sạn 5 sao.
Quản lý & vận hành bởi Silk Path Hotels & Resorts.
Tòa nhà boutique riêng tư chỉ 12 tầng, mỗi tầng 10 căn hộ.
Hầm đỗ xe thông minh, sảnh lễ tân sang trọng, an ninh 24/7.

Số lượng có hạn, mức giá cạnh tranh trong phân khúc, cùng tiềm năng gia tăng giá trị khi tuyến đường La Thành mở rộng và hạ tầng khu vực ngày càng hoàn thiện!', 'AVAILABLE', 'The Gloria by Silk Path, Đường Nguyên Hồng, Phường Láng Hạ, Quận Đống Đa, Hà Nội', 'Phường Láng Hạ', 'Quận Đống Đa', 'Hà Nội', 21.015850, 105.809200, 57.00, NULL, 2, 2, NULL, NULL, 'Sổ đỏ/ Sổ hồng', 7500000000.00, 'VND', NULL, NULL, NULL, NULL, NULL, NULL, '{"balcony_orientation":null,"commercial_subtype":null,"content_sha256":"ba38e7e9b2be8fc4123ab7978a7965fd38b737781b6502be7fdcd4151636f14e","crawled_at":"2026-08-06T07:05:21.459056Z","furniture_status":"Đầy đủ","last_seen_at":"2026-08-06T07:05:21.459056Z","listing_type":"SALE","market_insights":{"annual_change_direction":"UP","annual_change_percent":12.7,"history_points":[],"pricing_history_endpoint":"https://batdongsan.com.vn/Origins/CommonData/GetPricingHistory","pricing_history_endpoint_available":true,"pricing_history_fetched":false,"pricing_history_years":1},"price_per_sqm":131578947,"price_period":"TOTAL","privacy":{"direct_contact_policy":"MASKED_PUBLIC_PHONE_ONLY","free_text_contact_redactions":0},"project":{"name":null,"url":null},"raw_attributes":[{"label":"Khoảng giá","normalized_key":"source_price_per_sqm","normalized_value":7500000000,"raw_value":"7,5 tỷ"},{"label":"Diện tích","normalized_key":"area_sqm","normalized_value":57.0,"raw_value":"57 m²"},{"label":"Số phòng ngủ","normalized_key":"bedrooms","normalized_value":2,"raw_value":"2 phòng"},{"label":"Số phòng tắm, vệ sinh","normalized_key":"bathrooms","normalized_value":2,"raw_value":"2 phòng"},{"label":"Pháp lý","normalized_key":"legal_status","normalized_value":"Sổ đỏ/ Sổ hồng","raw_value":"Sổ đỏ/ Sổ hồng"},{"label":"Nội thất","normalized_key":"furniture_status","normalized_value":"Đầy đủ","raw_value":"Đầy đủ"}],"schema_version":"batdongsan-v1","seller":{"account_type":"UNKNOWN","active_listing_count":null,"avatar_url":"https://file4.batdongsan.com.vn/resize/200x200/2026/0