INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('bafbfaf2-8f16-5bc1-8380-0aecc4dec0b1', 'BDS_PR39055928', 'COMMERCIAL', 'Bán Shop Sao Biển 2 mặt tiền kinh doanh giảm 50% so với năm 2022 căn xẻ khe 145.6m2, giá 16 tỷ', 'Mở bán siêu phẩm.
SB - 103 Shophouse xẻ khe rẻ vô địch.

Diện tích đất: 145.6m².
DTXD: 427m².
Mặt tiền: 8m.
