INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('1fbe9f73-1372-552f-802d-dd3170ab11b4', 'BDS_PR45722040', 'APARTMENT', 'Bán CC G02, Khu đô thị Nam Thăng Long - Ciputra, giá cực chất 13 tỷ VND, 119m2, Hot!', 'Căn hộ chung cư G02, Khu đô thị Nam Thăng Long - Ciputra, Phường Phú Thượng, Hà Nội (cũ: Quận Tây Hồ, Hà Nội) với thiết kế hiện đại, tầng cao diện tích 119m², gồm 3PN + 2WC + bếp+1 chỗ đỗ xe ô tô. Căn hộ được trang bị đầy đủ nội thất như điều hòa, giường, tủ, TV, bếp từ, máy giặt, máy sấy quần áo, tủ lạnh, mang đến không gian sống thoải mái và tiện nghi. Hướng cửa chính: Nam, hướng ban công: Đông Nam, tạo không khí thoáng đãng và ánh sáng tự nhiên.
Pháp lý đầy đủ, giá bán 13 tỷ VND.

- Sẵn sàng để ở hoặc cho người Việt hoặc nước ngoài thuê
- Tầng cao, cửa sổ chính và ban công nhìn ra Hồ Tây thơ mộng, xem bắn pháo hoa tại nhà
- Gần trường học quốc tế, tạo điều kiện thuận lợi cho việc học tập của trẻ.
- Tiện ích xung quanh như chợ, siêu thị, công viên giúp nâng cao chất lượng cuộc sống.
- Đã bao gồm 1 chỗ đỗ xe ô tô cạnh tòa nhà.

