INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('1e5e7adb-ae6a-5cf0-a93d-4deb27f2870e', 'BDS_PR45641411', 'APARTMENT', 'Giá gốc CĐT căn góc 2PN 70,2m2 giá bán 3,99 tỷ bao thuế ký HĐMB trực tiếp CĐT TT 10% ký HĐMB ngay', 'Bán căn hộ resort Green Skyline, 3,99 tỷ, 70,2 m², 2PN, 2WC, giá ưu đãi, hot!

Căn hộ chung cư tại Green Skyline, Đường Quốc lộ 1K, Phường Đông Hòa, Hồ Chí Minh (Thành phố Dĩ An, Bình Dương cũ) nổi bật với không gian sống lý tưởng và tiện nghi hiện đại.

- Diện tích 70,2 m² với 2 phòng ngủ và 2 phòng tắm, phù hợp cho gia đình nhỏ.
- Hướng cửa chính Tây Nam và ban công Đông Bắc, đảm bảo ánh sáng tự nhiên và phong thủy tốt.
- Nội thất cơ bản đã bao gồm điều hòa, tủ lạnh, giường...
- Giá bán hấp dẫn 3,99 tỷ VND, đảm bảo giá trị đầu tư.

Tiện ích xung quanh:
+ Gần siêu thị Bách Hóa Xanh, đáp ứng nhu cầu mua sắm hàng ngày.
+ Trường mầm non song ngữ Rob Kids, thuận tiện cho gia đình có trẻ nhỏ.

