INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('3e003b07-2581-523c-a721-c17b484b9712', 'BDS_PR45227596', 'APARTMENT', 'Căn góc The Glen đã hoàn thiện giá chỉ 33 tỷ có sẵn hợp đồng thuê - Liên hệ em Hằng CĐT để xem nhà', 'Celadon City cực hot chương trình ưu đãi cuối năm khu Glen - Celadon City.
* The Glen - Celadon City | 20% nhận nhà | trực tiếp CĐT.
- Chiết khấu lên đến 27% cơ hội đầu tư và an cư cực tốt.

- Kế bên Aeon Mall Tân Phú.
- 3km đến sân bay Tân Sơn Nhất.
- 7km đến trung tâm TP.HCM, Đại lộ Đông Tây.

* The Glen còn được hưởng nhiều tiện ích đặc quyền như lối đi riêng, hầm để xe riêng, hệ thống an ninh, bảo mật 5 lớp, đảm bảo sự tiện nghi và riêng tư tối đa.

* Quy mô: 5,5ha | 98 căn Condo Villa giới hạn.
* Mật độ xây dựng: 28% | Cây Xanh: 12m/người.
* Thiết kế: 1 hầm oto, 1 trệt, 4 lầu.
* Diện tích đất: 5x19m.
* Diện tích sàn: 299,9m².
* Pháp lý: Sở hữu lâu dài.
* Sống biệt lập - Không gian xanh chuẩn nghỉ dưỡng - Giá trị bền vững.

* Có 3 phương thức thanh toán:
Phương thức 1: Chỉ 20% ~ 5t nhận nhà, số còn lại thanh toán giãn đến 36 tháng.
Phương thức 2: Chỉ 30% ~ 6t nhận nhà, số còn lại bank giải ngân, CĐT trả lãi 7% lên đến 24 tháng.
Phương thức 3: Chỉ 20% nhận nhà sau 1 tháng bổ sung 75% để nhận chiết khấu khủng.

Ưu đãi booking hôm nay:
Chiết khấu tân gia: 15%.
Chiết khấu theo PTTT: 1% đến 3%.
Chiết khấu đặc biệt: 10%.
Miễn phí hội viên CLB thể thao 1 năm.
Tặng thẻ phòng chờ sân bay 2 năm.

