INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('9d3ff4cf-24ff-5ae5-9c05-0f7d0ca3e9b5', 'BDS_PR45905560', 'APARTMENT', 'Bán nhanh 2PN - 2,1 tỷ, CC Dream Home Palace, kèm nội thất (2,2 tỷ 62m2)', 'Dream Home Palace, đường Trịnh Quang Nghị, phường Bình Đông, Hồ Chí Minh, trước đây quận 8, Hồ Chí Minh là một căn hộ chung cư nổi bật với diện tích 62m², được thiết kế hiện đại và tiện nghi. Căn hộ này có 2 phòng ngủ, 2 phòng WC, hứa hẹn sẽ đem đến không gian sống thoải mái cho gia đình.

+ Giá bán: 2,1 tỷ - 2,2 tỷ VND.
+ Nội thất cơ bản đầy đủ. (Để lại, 2 máy lạnh, 1 tủ quần áo âm tường, 2 giường, 1 máy giặt, 1 Máy nước nóng, 1 tivi + kệ, 1 bàn ăn, Bếp từ).
+ Hướng cửa chính: Tây bắc, hướng ban công: Đông nam.

Điểm đặc sắc: Căn hộ nằm trong khu dự án Dream Home Palace phường 7 quận 8 (củ), CC có nhiều tiện ích như hồ bơi, và khu vui chơi trẻ em, CAFE, ăn uống. Chợ - trường - BHX, nhà thuốc ngay dưới chân chung cư, tất cả đều được thiết kế để phục vụ nhu cầu sống hiện đại và tiện nghi.
- (Cần tiền sớm, ưu tiên không vay ngân hàng).

