INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('3c68b546-e557-5e5a-9eb1-f1e94f1cd2b8', 'BDS_PR46136708', 'LAND', 'Bán đất đẹp, thổ cư rất nhiều (846.7m2 - 580 thổ cư), giá thấp hơn NH định giá, có thể chia 6-8 nền', 'Khu đất nằm Lô C, cầu kênh 3, gần trường tiểu học An Hạ:
- Diện tích 846.7m² - Thổ cư 580 m² - thổ cư rất nhiều.
- Giá bán: 12 tỷ (ngân hàng định giá 12 tỷ 62 triệu - có kèm biên bản định giá), bớt lộc.
- Giá ~ 14 tr/m².
- Nền đổ đất cao ráo, cất nhà ngay, có hàng rào bao quanh, có hồ thư giãn nhỏ trong vườn.
- Ngang 20m x dài 42.5m; 2 mặt tiền.
- Có thể chia 6 nền (theo quy định hiện tại), tương lai có thể chia 8 nền.
- Cách Vinhomes Sài Gòn Park và ga Metro - 10 phút.
- Gần Vành Đai 3, đi vào trung tâm mất 20 - 30 phút.
- Tương lai có siêu thị xây trong khu dân cư An Hạ (phía sau đất).
- Ngay chợ, trường tiểu học An Hạ và cầu kênh 3 đi qua đường Thanh Niên (khu sầm uất của đường An Hạ).
- Mặt tiền rộng 20m, cực kì thuận lợi cho việc kinh doanh căn hộ dịch vụ, nhà trọ, nhà xưởng, biệt thự nghỉ dưỡng.
- Hẻm đi được 2 xe ô tô.
- Pháp lý đầy đủ (vay được ngân hàng).

