INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('9efbd8c0-9e76-5603-b9c6-1afb843d863f', 'BDS_PR45703650', 'APARTMENT', 'Beverly bán căn 2PN 80m2 layout căn siêu hiện đại - tinh tế - sang trọng VHGP', 'The Beverly - Chính sách mới tháng 8/2026 ưu đãi khi mua thanh toán tiền mặt 95% hoặc sử dụng vay ngân hàng giải ngân.
Nhận nhà khai thác cho thuê hoặc để ở ngay.

- Căn 2PN căn layout bo tròn và vuông vức siêu hiện đại, thông thoáng đón nắng và đón gió.

- Có phòng bếp đảo riêng tư, sạch sẽ.
- Ban công siêu dài nơi có thể decor vườn cây xanh mát, bàn trà siêu thư giãn.

- Giá sau các ưu đãi chỉ cần 30% khoảng 1.6 tỷ, số còn lại vay ngân hàng hoặc thanh toán đủ tiền mặt nhận nhà khai thác vô nội thất cho thuê và để ở ngay được.
- View công viên nội khu, tầm view 1 phần pháo hoa.

= Đặc biệt với The Beverly CĐT sẽ thiết kế riêng nguyên 1 tầng 14 dành cho cư dân để sử dụng các tiện ích cao cấp như phòng Zone kid, Bida, hệ thống phòng Gym đầy đủ các máy tập luyện, phòng họp đầy đủ các thiết bị bàn ghế sang trọng để tiếp khách, học tập...

= Tiện ích nội khu có hồ bơi Marina nước mặn tốt cho sức khoẻ, hệ công viên có đài phun nước rất Chile...

= Sảnh lễ tân theo tiêu chuẩn 5 sao.
