INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('fc3f1c1c-4f48-5edf-ae44-7512fe6a3806', 'BDS_PR46138547', 'VILLA', 'Bán biệt thự đơn lập, căn gốc Gladia 260m2 Keppel Land, Quận 2, TP. Hồ Chí Minh', 'Bán biệt thự đơn lập, căn gốc tại đường Võ Chí Công, quận 2, thành phố Hồ Chí Minh.
Do chủ đầu tư Keppel Land Singapore và Khang Điền hợp tác phát triển.

Biệt thự là căn gốc 2 mặt sân vườn + view sông bao quanh nhà.
3 mặt giáp sông
5 công viên 1,25 hecta
4 khu BBQ nướng ngoài trời
2km đường chạy bộ
Khu an ninh khép kính

Biệt thự riêng, hoàn thiện xây dựng, hoàn chỉnh pháp lý.
Pháp lý: đã có GCN lô đất - Ký HĐMB cấp GCN đất và tài sản gắn liền với đất cho quý.
Nhà đã xây dựng xong, mới 100%.

Diện tích đất: 260-293m2
Diện tích xây dựng: 341m2
Xây dựng 3 tầng: 4-5 phòng ngủ + 5 WC.
Lùi trước 3m sau 2m (bên hong chừa 2-2m)

Giá GỐC từ chủ đầu tư: 69,7- 85,3 tỷ (chưa VAT).
Chiết khấu lên đến 8-9 tỷ
Khi khách hàng chọn thanh toán nhanh: CK8%
Tặng 1 xe hơi Mercides: 2,1 tỷ
Không nhận chứng thư bão lãnh: CK 0,5%
Mừng Tân gia Phú Quý tặng 50 triệu

Nhiều phương thức thanh toán theo tiến độ.
Cọc 200tr -15 ngày sau ký HĐMB thanh toán 20%+ 10% mỗi 3 tháng tiếp theo

Hoặc vay ngân hàng Vietinbank, VCB, BIDV
Vay tối đa 75% trong 18 tháng lãi suất 0%

