INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('1da4ea28-06e8-5738-8350-c33ad90bd4bd', 'BDS_PR46086775', 'APARTMENT', 'S-Light Tower-căn 2pn-tầng cao-giá mua ngay đợt đầu trực tiếp cđt Sun Group - hỗ trợ vay đến 70%', 'S-Light Tower đang trở thành tâm điểm mới tại giao lộ 29/3 & Nguyễn Đình Thi với mức giá cực kì hấp dẫn.

Liên hệ ngay: 0935 013 *** (Thùy Ngân) để được cập nhật thông tin và tư vấn chi tiết.

* Vị trí chiến lược:
- Ngay trung tâm thành phố - gần các khu mua sắm, giải trí.
- Gần biển Mỹ Khê - không khí sạch, view biển tuyệt đẹp.
- Giao thông thuận tiện - liên kết nhanh tới mọi điểm.

* Tiện ích nổi bật:
- Hồ bơi vô cực với view tuyệt đẹp + Gym hiện đại.
- Căn hộ sang trọng, nội thất cao cấp.
- An ninh 24/7 với hệ thống camera & bảo vệ.
- Công viên xanh rộng, không gian yên tĩnh.
- Bãi xe tầng hầm, đủ chỗ & an toàn.
- Smart home, thang máy siêu tốc, tiện ích đầy đủ.

* Tại sao chọn S Light Tower?
- Đầu tư sinh lợi: Giá trị tăng trưởng ổn định.
- Chất lượng sống cao: Thiết kế sang trọng, môi trường sạch.
- Cộng đồng cư dân chất lượng.
- Gần trường học, bệnh viện, trung tâm thương mại.
- Hỗ trợ pháp lý & tài chính toàn diện.

* Khách hàng thanh toán tiến độ chỉ cần thanh toán 70% nhận nhà, 30% còn lại thanh toán trong vòng 2 năm kể từ ngày nhận nhà.
Chính sách chiết khấu lên đến 19%.

HTLS lên đến 24 tháng.
Thanh toán theo tiến độ trong 48 tháng.
Thanh toán 70% nhận nhà ngay.

