INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('e8b4cf21-4582-5763-9623-d399b1a79b20', 'BDS_PR46107578', 'APARTMENT', 'Căn hộ D-Aqua, bán căn 49m2-3,4 tỷ, 54m2-3,9. 68m2-4,5 tỷ. 71m2-4,8 tỷ, mini Gaarden 4,65tỷ tại Q8', 'Căn hộ D - Aqua, đường Bến Bình Đông, phường Phú Định, Hồ Chí Minh, trước đây Quận 8, Hồ Chí Minh là một lựa chọn lý tưởng cho những ai muốn sống giữa lòng thành phố với không gian sống tiện nghi và hiện đại.

- Căn Studio 31m² giá 2,4 tỷ.
- Căn 1PN 49m² giá 3,4 tỷ.
- Căn 2PN - 1WC 54m² giá 3,9 tỷ.
- Căn 2PN - 2WC 68m² giá 4,5 tỷ.
- Căn 2PN - 2WC 71m² căn góc giá 4,8 tỷ.
- Căn 2PN Mini Garden có ban công rộng 8m giá 4,65 tỷ.
- Căn 2PN + 1 74m² căn góc giá 4,9 tỷ.
- Căn 3PN - 2WC 82m² giá 5,8 tỷ.
Hỗ trợ vay ngân hàng lên đến 80% và nhanh chóng, duyệt cả hồ sơ khó tại Publicbank, Liên Việt Bank, TpBank, MBbank.

Dự án đang trong quá trình bàn giao với nội thất cơ bản xịn xò, chất lượng, tiện nghi..

+ Sảnh đón sang trọng và khu mua sắm ngay trong dự án, tiện lợi cho việc sinh hoạt.
+ Hồ bơi tràn bờ và công viên bờ sông mang đến không gian thư giãn tuyệt vời.
+ Phòng gym và khu vui chơi trẻ em giúp cả gia đình có thể tận hưởng cuộc sống thật vui vẻ.
+ Skybar và khu vực cafe lý tưởng cho những buổi tối thư giãn.

