INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('970ef8ed-5535-5cf1-9da2-cf854ed12164', 'BDS_PR46135884', 'VILLA', 'Nhà phố sở hữu lâu dài 4 tầng khu kinh doanh ẩm thực, lưu trú. Giá tháng 8/2026 10-11 tỷ/căn', 'Với quy mô 2.870ha cùng hệ sinh thái tiện ích nổi bật thế giới, Vinhomes Green Paradise không chỉ là một thành phố biển mới đang được hình thành tại TP. HCM mà còn là dự án có tầm nhìn trở thành khu đô thị ESG nổi bật thế giới, thể hiện đẳng cấp về ESG ++ của Việt Nam trên bản đồ toàn cầu.

* Đừng mua Vinhomes Cần Giờ chỉ vì đầu tư mà hãy mua nhà Vinhomes Cần Giờ anh chị mua ngôi nhà bên biển sánh ngang thế giới, vì những hạng mục sau đây đang được thi công để 3 năm nữa Cần Giờ sẽ trở thành thiên đường sống.

- Cầu Cần Giờ 13,200 tỷ đồng (đang thi công dự kiến hoàn thành 2029).
- Đường cao tốc Bến Lức Long Thành (thông xe toàn tuyến 2026).
- Metro Bến Thành - Cần Giờ 350km/h (đang thi công dự kiến hoàn thành cuối 2028).
- Cầu vượt biển Cần Giờ - Vũng Tàu (đã khởi công dự kiến hoàn thành 2029).
- Siêu cảng quốc tế Cần Giờ (sắp triển khai).
- Nút giao Rừng Sác (đặc biệt quan trọng khi đưa vào vận hành sẽ di chuyển bẳng đường bộ 100% không còn "ngăn sông" khi nhắc đến Cần Giờ).

* Các tiện ích tiêu biểu tại dự án.
- Nhà hát sóng xanh Quốc tế.
- Khu ẩm thực kinh tế đêm 24/7 Cosmo Bay.
- Trung tâm thương mại Vincom.
- Sân golf 155 ha.
- Công viên giải trí chủ đề 120ha.
- Trung tâm mua sắm outleft 20ha (mua sắm hàng hiệu giá tốt - miễn thuế).
- Tháp Land Mark 108 tầng.
- Biển hồ Lagoona 800 ha.
- Hệ thống chuỗi thương hiệu khách sạn 5 - 6 sao top đầu thế giới.

* Các dòng sản phẩm chính.
Nhà phố liền kề: 1 trệt 3 tầng lầu (hoàn thiện bên ngoài thô bên trong).
- Diện tích 75m², 80m²,100m² (giá bán 10,5 tỷ - 17 tỷ).

Biệt thự song lập: 1 trệt 2 lầu sở hữu bãi tắm riêng cát trắng sau nhà.
- Diện tích: 189m², 230m², 280m².

Biệt thự đơn lập (giá từ 45 tỷ - 100 tỷ).
- Diện tích 250m², 350m², 500m².

Lịch thanh toán:
Vốn ban đầu 30% - ngân hàng giair ngân 70%. (miễn lãi 18 tháng ko đóng gốc lãi).
Thời điểm nhận nhà theo khu vực:
Khu xây sẵn: Bàn giao tháng 10/2026.
Khu xây thô: Bàn giao cuối năm 2027.
Khu xây giãn: Bàn giao cuối năm 2028.

Liên hệ Bình DT, CVKD chuyên trực tại Vinhomes Cần Giờ: 0978 770 ***.
Hỗ trợ tư vấn, báo giá, giỏ hàng, có xe đưa đón khách tham quan khách hàng từ sân bay Tân Sơn Nhất, hoặc khách hàng ở TP HCM.', 'AVAILABLE', 'Vinhomes Green Paradise , Xã Long Hòa, Huyện Cần Giờ, Hồ Chí Minh', 'Xã Long Hòa', 'Huyện Cần Giờ', 'Hồ Chí Minh', 10.385860, 106.919900, 80.00, NULL, 3, 3, NULL, NULL, 'Hợp đồng mua bán', 10700000000.00, 'VND', NULL, NULL, NULL, NULL, NULL, NULL, '{"balcony_orientation":null,"commercial_subtype":null,"content_sha256":"3e9792d0fc42c639339c15afafebd6324a6a5a3f6ebdc14fe064328ac4af9da7","crawled_at":"2026-08-06T07:11:37.258394Z","furniture_status":"Không nội thất","last_seen_at":"2026-08-06T07:11:37.258394Z","listing_type":"SALE","market_insights":{"annual_change_direction":"UP","annual_change_percent":37.8,"history_points":[],"pricing_history_endpoint":"https://batdongsan.com.vn/Origins/CommonData/GetPricingHistory","pricing_history_endpoint_available":true,"pricing_history_fetched":false,"pricing_history_years":1},"price_per_sqm":133750000,"price_period":"TOTAL","privacy":{"direct_contact_policy":"MASKED_PUBLIC_PHONE_ONLY","free_text_contact_redactions":0},"project":{"name":null,"url":null},"raw_attributes":[{"label":"Khoảng giá","normalized_key":"source_price_per_sqm","normalized_value":10700000000,"raw_value":"10,7 tỷ"},{"label":"Diện tích","normalized_key":"area_sqm","normalized_value":80.0,"raw_value":"80 m²"},{"label":"Số phòng ngủ","normalized_key":"bedrooms","normalized_value":3,"raw_value":"3 phòng"},{"label":"Số phòng tắm, vệ sinh","normalized_key":"bathrooms","normalized_value":3,"raw_value":"3 phòng"},{"label":"Số tầng","normalized_key":"total_floors","normalized_value":4,"raw_value":"4 tầng"},{"label":"Pháp lý","normalized_key":"legal_status","normalized_value":"Hợp đồng mua bán","raw_value":"Hợp đồng mua bán"},{"label":"Nội thất","normalized_key":"furniture_status","normalized_value":"Không nội thất","raw_value":"Không nội thất"}],"schema_version":"batdongsan-v1","seller":{"account_type":"UNKNOWN","active_listing_c