INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('5d150147-0f08-5c8a-9400-779b2c2e815d', 'BDS_PR45366991', 'HOUSE', 'Giảm 400tr Chính chủ bán gấp nhà 4 tầng giá 5,35 tỷ/~55m2 đất, Đ.Trường Lưu P.Long Trường, HCM', 'GIẢM GIÁ 400TR CẦN BÁN GẤP
Chính chủ bán nhà hẻm 45 Trường Lưu (sau chợ Long Trường) Phường Long Trường, TP. HCM.
Nhà xây để ở do cần tiền nên bán gấp.
1/ Kết cấu: Nhà kết cấu 4 tầng bê tông cốt thép có bản vẽ xây dựng (đang xin hoàn công).
- Móng: Sử dụng cọc BTCT 250*250 mác 250 ép tĩnh tải đầu cọc 90 tấn.
- Tầng 1: Gồm 01PK, 01 phòng ăn, Bếp, 01 nhà vệ sinh (xây sau hoàn công), lùi sau 1m lấy không khí, lùi trước 2,4m chỗ để xe máy.
- Tầng 2: 02PN, 01 toilet, ban công phía trước.
- Tầng 3: 02PN, 01 toilet, ban công phía trước.
- Tầng 4: Sân thượng phía trước, sân thượng phía sau, 01 Toilet. Không gian sân thượng thoáng mát buổi tối ngồi hóng gió.
- Mái: Mái tum thang đặt bồn nước.
- Diện tích đất ~55m²; diện tích sàn 160m².
2/ Vị trí: Mặt tiền hẻm 45 đường Trường Lưu hẻm không bị ngập nước.
3/ Tiện ích:
- 2p đi bộ ra chợ Long Trường.
- 5p đi bộ ra khu đô thị Đông Tăng Long.
- 3P đi xe ra UBND, trường học cấp 1,2,3.
- Bán kính 2 - 3km ra trường đại học FPT, khu CNC, Trường ĐH tài chính Marketing, Khu đô thị Vinhomes Grand Park.
- Hẻm xe hơi trước nhà 7m có vỉa hè.
4/ Pháp lý: Sổ hồng, nhà có thiết kế và hoàn công đầy đủ.
* Khách hàng an tâm về mặt chất lượng, nhà xây để ở nên tuân thủ 100% bản vẽ thiết kế đưa ra (thiết kế cũng thuê đơn vị chuyên thiết kế các công trình nhà ở dân dụng).
