INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('59bcdd83-ae5b-5845-8557-90b4d122794a', 'BDS_PR45704725', 'VILLA', 'Bán căn biệt thự view hồ giá tốt cạnh tranh, hàng trực tiếp CĐT cách Hà Nội 30 phút di chuyển', 'Biệt thự Thanh Xuân Valley, Phường Xuân Hòa, Phú Thọ - Thành phố Phúc Yên, Vĩnh Phúc cũ là một lựa chọn phù hợp cho những ai tìm kiếm không gian sống sang trọng và tiện nghi.
- Diện tích rộng rãi 324m², phù hợp cho gia đình lớn.
- Thiết kế 4 tầng với 5 phòng ngủ và 5 phòng tắm, đáp ứng đầy đủ nhu cầu sinh hoạt.
- Nội thất đầy đủ với các trang bị như điều hòa, tủ lạnh và giường.
- Hướng cửa chính Đông Nam, ban công hướng Nam, mang lại phong thủy tốt cho gia chủ.
- Ngõ vào rộng 13m, thuận tiện cho việc di chuyển và đậu xe.
- Mặt tiền 18m, lý tưởng cho các hoạt động kinh doanh hoặc cho thuê.
