INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('ccf92627-7a0a-58e4-a7b6-8a262ab1b2e6', 'BDS_PR45265024', 'APARTMENT', 'Chỉ 2,5 tỷ sở hữu ngay căn hộ view biển Full nội thất, bàn giao ngay, khai thác đến 25 triệu/tháng', 'BÁN GẤP CĂN HỘ VIEW TRỰC DIỆN BIỂN MỸ KHÊ CHỈ 2,5 TỶ!

Ông anh ở quê đang cần vốn kinh doanh nên nhờ em bán gấp căn hộ biển vị trí đẹp ngay mặt tiền đường Võ Nguyên Giáp, đối diện biển Mỹ Khê.

Thông tin căn hộ:
Diện tích gần 38m²
Ban công view trực diện biển cực đẹp
Tầng cao, thoáng mát
Full nội thất cao cấp Chỉ xách vali vào ở
Hiện đang cho thuê khoảng 25 triệu đồng/tháng
Tiện ích đầy đủ: Hồ bơi, phòng gym, nhà hàng, lễ tân, an ninh 24/7...

Giá bán nhanh chỉ 2,5 tỷ
Đã bao gồm VAT và phí bảo trì.

Đây là căn hộ cần bán gấp nên mức giá đang rất cạnh tranh so với nhiều sản phẩm cùng phân khúc trong khu vực.

