INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('3866be79-3b49-51a8-bedb-bac703ff0287', 'BDS_PR45916038', 'HOUSE', 'Nhà phố Quận 8, Khu dân cư Hai Thành, Trịnh Quang Nghị', 'Diện tích 4m x 24m, 4 tầng + sân thượng. Gara để ô tô trong nhà. Sân trước, sân sau thoáng mát. Hoàn công đầy đủ năm 2025. Nhà mới, xây dựng kiên cố, chắc chắn. Thiết kế đẹp, dọn vào ở ngay. Gần Làng Đại học. Gần trường cấp 1, 2, 3. Kết nối thuận tiện đến Vành đai 3. Đường Phạm Thế Hiển chuẩn bị mở rộng. Dự án cầu Bình Tiên đang triển khai kết nối khu vực. Không gian gần 3 mặt sông, thoáng mát quanh năm. Khu dân cư yên tĩnh, văn minh. Tiềm năng tăng giá tốt nhờ hạ tầng phát triển.', 'AVAILABLE', '61 đường 3158c, Khu dân cư Phú Lợi, Đường Phạm Thế Hiển, Phường 7, Quận 8, Hồ Chí Minh', 'Phường 7', 'Quận 8', 'Hồ Chí Minh', 10.702760, 106.621600, 96.00, NULL, 5, 5, NULL, 'Tây', 'Sổ đỏ/ Sổ hồng', 7700000000.00, 'VND', NULL, NULL, NULL, NULL, 4.00, 10.00, '{"balcony_orientation":"Tây","commercial_subtype":null,"content_sha256":"e806c044758618205109507e5ac02a1295ea58e5da9f918efc75cd931bac4865","crawled_at":"2026-08-06T07:11:37.258394Z","furniture_status":"Đầy đủ","last_seen_at":"2026-08-06T07:11:37.258394Z","listing_type":"SALE","market_insights":{"annual_change_direction":"UP","annual_change_percent":26.9,"history_points":[],"pricing_history_endpoint":"https://batdongsan.com.vn/Origins/CommonData/GetPricingHistory","pricing_history_endpoint_available":true,"pricing_history_fetched":false,"pricing_history_years":1},"price_per_sqm":80208333,"price_period":"TOTAL","privacy":{"direct_contact_policy":"MASKED_PUBLIC_PHONE_ONLY","free_text_contact_redactions":0},"project":{"name":null,"url