2026","listing_id_text":"45916038","listing_tier":"Tin VIP Kim Cương","published_text":"04/08/2026"},"source_price_per_sqm":80210000,"source_product_type":38,"source_secondary_address":"(Phường Bình Đông, Hồ Chí Minh mới)","source_updated_at":"2026-08-06T09:58:07.586000+07:00","source_url":"https://batdongsan.com.vn/ban-nha-rieng-duong-pham-the-hien-phuong-7-6-khu-dan-cu-phu-loi/pho-sieu-ep-4-tang-hoan-cong-ay-u-7-7t-pr45916038","source_videos":[],"total_floors":4,"verification":{"source_verified":false,"source_vip_type":0}}'::jsonb, '2026-08-04T08:17:42.715000+07:00'::timestamptz) ON CONFLICT (code) DO UPDATE SET property_kind = EXCLUDED.property_kind, title = EXCLUDED.title, description = EXCLUDED.description, address_line = EXCLUDED.address_line, ward = EXCLUDED.ward, district = EXCLUDED.district, province = EXCLUDED.province, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, area_sqm = EXCLUDED.area_sqm, usable_area_sqm = EXCLUDED.usable_area_sqm, bedrooms = EXCLUDED.bedrooms, bathrooms = EXCLUDED.bathrooms, floor_number = EXCLUDED.floor_number, orientation = EXCLUDED.orientation, legal_status = EXCLUDED.legal_status, list_price = EXCLUDED.list_price, currency = EXCLUDED.currency, parcel_number = EXCLUDED.parcel_number, map_sheet_number = EXCLUDED.map_sheet_number, land_use_purpose = EXCLUDED.land_use_purpose, land_use_term = EXCLUDED.land_use_term, frontage_m = EXCLUDED.frontage_m, road_width_m = EXCLUDED.road_width_m, features = EXCLUDED.features, published_at = EXCLUDED.published_at, status = CASE WHEN properties.status IN ('DRAFT', 'AVAILABLE') THEN EXCLUDED.status ELSE properties.status END, updated_at = now();
