INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('29138084-8b2c-55e8-a9b0-65b0eae61737', 'BDS_PR46130616', 'LAND', 'Chỉ 1,65 tỷ sở hữu khu đất hai mặt tiền hiếm có bên hồ Nông trường 4, Phú Riềng', 'Có những mảnh đất chỉ để sở hữu.

Và cũng có những mảnh đất để tận hưởng cuộc sống.

Đây là một trong số đó.

Chính chủ cần chuyển nhượng khu đất rộng 2.314,6 m², gồm 2 sổ riêng liền kề, nằm ngay mặt hồ Nông trường 4 Phú Riềng, Bình Phước.

Điểm đặc biệt của khu đất là sở hữu hai mặt tiền hiếm có:

Mặt trước tiếp giáp đường nhựa rộng 6 m, chiều ngang khu đất khoảng 20 m, ô tô vào tận nơi.

Mặt sau giáp hồ Nông trường 4, nở hậu hơn 20 m, mở ra không gian mặt nước rộng lớn, thoáng đãng và riêng tư.

Thông tin khu đất.

* Tổng diện tích: 2.314,6 m².
* Gồm 2 sổ riêng:
* Thửa 143: 1.056,5 m².
* Thửa 144: 1.258,1 m².
* Đất trồng cây lâu năm.
* Pháp lý rõ ràng, sang tên nhanh.
* Chính chủ bán, hỗ trợ xem đất trực tiếp.

Phù hợp để.

Nhà vườn nghỉ dưỡng.

Khu câu cá cuối tuần.

Retreat giữa thiên nhiên.

Hoặc đầu tư đón tiềm năng phát triển khu vực.

Điều khiến khu đất này khác biệt không chỉ là diện tích, mà là không gian ven hồ trong lành, tầm nhìn rộng mở và cảm giác bình yên mà rất ít bất động sản còn giữ được.

Nếu bạn đang tìm một nơi để vừa gìn giữ tài sản, vừa tạo nên một không gian nghỉ dưỡng của riêng mình, đây là một lựa chọn dành cho bạn.

Giá bán: 1,65 tỷ (thương lượng trực tiếp với chính chủ).

