INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('c09ad119-43b8-5ba6-8b8f-cafae5d6c50e', 'BDS_PR44829225', 'HOUSE', 'Bán nhà phố Hồ Tùng Mậu 45m2 8 tầng MT 5m 17tỷ có TL, thang máy, kinh doanh, gara ô tô tránh', 'Vị trí nhà siêu đẹp, cách mặt phố Hồ Tùng Mậu chỉ 50m, vài bước ra ga tàu điện trên cao, giao thông cực kỳ thuận tiện.
DT 45m² CN 42m².
Nhà lô góc, 2 mặt thoáng, ngõ trước nhà 4m, ô tô qua, mặt ngõ kinh doanh sầm uất, phù hợp mọi loại hình: Spa, hiệu thuốc, thời trang, nails, tóc, tạp hoá.
Toàn bộ nội thất nhà làm bằng gỗ Gõ chắc chắn, thang máy nhập khẩu chạy êm.

Thiết kế hiện đại, sang trọng:
- Tầng 1: Cửa hàng kinh doanh.
- Tầng 2: Thông sàn, khép kín.
- Tầng 3: Thông sàn, khép kín.
- Tầng 4: Thông sàn, khép kín.
- Tầng 5: Thông sàn, khép kín.
- Tầng 6: Bếp + phòng khách.
- Tầng 7: Phòng thờ + sân phơi.
- Tầng 8: Sân vườn, tum thư giãn.

- Miễn TG, QC làm phiền.
- Cam kết thông tin thật.

- Chào bán giá tốt trên thị trường.
