INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('838446e7-695f-58c2-b67e-06f4900d6f42', 'BDS_PR44695913', 'APARTMENT', 'Chủ đầu tư Bcons Newsky 2PN = 2.7tỷ, 3PN = 3.6tỷ, rõ ràng thuê 15tr/tháng, tt 20% nhận nhà - 0% lãi', 'Phòng kinh doanh Chủ đầu tư Bcons cung cấp giỏ hàng giá niêm yết, mua trực tiếp chủ đầu tư dự án Bcons NewSky - mặt tiền Quốc Lộ 13, qua Thủ Đức, Quận 12 chỉ 10p chạy xe:
CDT hỗ trợ cho thuê lại 12tr - 15tr/tháng - Miễn Phí Quản lý 24 tháng, Tặng 1.5 chỉ vàng áp dụng cho:
- Căn hộ 2PN - 1WC có giá từ 2,4 tỷ, tặng ngay 1,5 chỉ vàng.
- Căn hộ 2PN - 2WC có giá từ 2,7 tỷ, tặng ngay 1,5 chỉ vàng.
- Căn hộ 2PN - 2WC diện tích lớn 65,54m² - 73,85m² có giá từ 3 tỷ, tặng ngay 1,5 chỉ vàng.
- Căn hộ 3PN có giá từ 3,6 tỷ.
- Thanh toán chỉ 20% tới nhận nhà. Ân hạn gốc lên tới 10 năm, góp vốn bậc thang chỉ 200k/tháng, miễn lãi tới khi nhận nhà nếu sử dụng phương thức vay ngân hàng.
- Dự án còn rất nhiều vị trí đẹp cho khách lựa chọn, liên hệ em để chọn vị trí yêu thích nhé khách: 0935 316 ***.
-------------------------------------------------
Phương thức thanh toán với tiêu chí ai cũng có thể sở hữu: Thanh toán chậm trong vòng 24 tháng.
- Thanh toán chỉ 5% giá trị căn hộ cho tới quý IV/2026 mới thanh toán tiếp. Mỗi tháng chỉ đóng 3%.
- Ngân hàng bảo lãnh cho vay maximum 80% giá trị căn hộ, ân hạn gốc và miễn lãi tới khi nhận nhà.
- Tiện ích vượt trội với hơn 79 tiện ích lớn nhỏ. Hồ bơi trên cao tràn bờ vô cực chuẩn Olympic diện tích cực khủng 1200m².
- Có tới 3 phòng tập gym, yoga, khu sân vườn trên cao cực chill.
- Trường mầm non Quốc tế Bschool Chủ đầu tư Bcons tự vận hành.
Đa dạng loại hình hộ với mật độ xây dựng chỉ hơn 30% cực thoáng:
+ Căn hộ ở 2PN và 3PN có đủ các diện tích lớn nhỏ, thiết kế độc đáo với ban công dài rộng full chiều dài phòng khách không bị chắn view.
+ 29 căn thương mại shophouse kinh doanh cực nhộn nhịp.
+ Căn hộ sân vườn trên cao Sky Garden cực hiếm.
Giá tốt khu vực chỉ với hơn 1500 căn, số lượng căn hộ cực cạnh tranh.
- Pháp lý chuẩn đã có Giấy Phép Xây Dựng và đã khởi công từ tháng 10/2025.
- Chủ đầu tư và phát triển dự án, xây dựng: BCONS tốt trên thị trường với gần 20 dự án đã và đang bàn giao có sổ đúng tiến độ cho khách hàng.
------------------------------
Gọi hotline 0935 316 *** Phòng Kinh doanh CDT Bcons NewSky để xem bảng giá và vị trí căn chi tiết chuẩn xác nhất.', 'AVAILABLE', 'Bcons NewSky, Đường Quốc Lộ 13, Phường Lái Thiêu, Thành phố Thuận An, Bình Dương', 'Phường Lái Thiêu', 'Thành phố Thuận An', 'Bình Dương', 10.890047, 106.703220, 60.00, NULL, 2, 2, NULL, NULL, 'Hợp đồng mua bán', 2700000000.00, 'VND', NULL, NULL, NULL, NULL, NULL, NULL, '{"balcony_orientation":"Đông Nam","commercial_subtype":null,"content_sha256":"747abb4300b986d4baf73fd2bd6d152b0e9cd53fcc7455ad061b21b18a10d3e7","crawled_at":"2026-08-06T07:11:37.258394Z","furniture_status":"Đầy đủ","last_seen_at":"2026-08-06T07:11:37.258394Z","listing_type":"SALE","market_insights":{"annual_change_direction":"UP","annual_change_percent":23.0,"history_points":[],"pricing_history_endpoint":"https://batdongsan.com.vn/Origins/CommonData/GetPricingHistory","pricing_history_endpoint_available":true,"pricing_history_fetched":false,"pricing_history_years":1},"price_per_sqm":45000000,"price_period":"TOTAL","privacy":{"direct_contact_policy":"MASKED_PUBLIC_PHONE_ONLY","free_text_contact_redactions":0},"project":{"name":null,"url":null},"raw_attributes":[{"label":"Khoảng giá","normalized_key":"source_price_per_sqm","normalized_value":2700000000,"raw_value":"2,7 tỷ"},{"label":"Diện tích","normalized_key":"area_sqm","normalized_value":60.0,"raw_value":"60 m²"},{"label":"Số phòng ngủ","normalized_key":"bedrooms","normalized_value":2,"raw_value":"2 phòng"},{"label":"Số phòng tắm, vệ sinh","normalized_key":"bathrooms","normalized_value":2,"raw_value":"2 phòng"},{"label":"Hướng ban công","normalized_key":"balcony_orientation","normalized_value":"Đông Nam","raw_value":"Đông - Nam"},{"label":"Pháp lý","normalized_key":"legal_status","normalized_value":"Hợp đồng mua bán","raw_value":"Hợp đồng mua bán"},{"label":"Nội thất","normalized_key":"furniture_status","normalized_value":"Đầy đủ","raw_value":"Đầy đủ"}],"schema_version":"batdongsan-v1","seller":{"account_type":"BROKER","