INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('df3f9041-436f-536e-b8ea-b0700cc3f01b', 'BDS_PR45045255', 'APARTMENT', 'Đừng bỏ lỡ! Căn hộ hàng hiệu SG - The Global City (Masteri CT3) BĐS hạng A - Sở hữu ngay 0902 999 ***', 'Chính thức nhận booking 100 triệu/suất (có hoàn lại) ~ Khách booking sớm được tặng nhiều chính sách hấp dẫn trực tiếp từ chủ đầu tư Masteri Homes:
Masteri Park Place (CT5).
Masteri Cosmo Central (CT4).
Masteri Nexus Zone (CT3).

1) Loại hình căn hộ.
- Căn 1PN, 1PN + : 47m², 53m², 57m².
- Căn 2PN: 73m², 76m², 81.7m².
- Căn 3PN: 100m² đến 120m².
- Căn 4PN: 120m² đến 150m².
- Căn hộ duplex & penthouse.

* Liên hệ ngay văn phòng Masteri Homes: 0902 999 *** Mr Sỹ để được hỗ trợ lấy căn giá tốt trực tiếp từ CĐT.
------------------------------
2) Chính sách bán hàng.
* Gía bán căn hộ Masteri Cosmo Central:

- 1PN, 1PN + 1, 1WC giá từ 6.5 tỷ.

- 2PN, 2WC giá từ 7.9 tỷ. (Giá thanh toán nhanh 7.5 tỷ).

- 3PN, 2WC giá từ 12 tỷ.

- 4PN, 3WC giá từ 16 tỷ.

* Chính sách ưu đãi trong tháng 01/2026:

- Thanh toán theo tiến độ: CK 7%.

- Thanh toán nhanh: CK 14%.

- Khách hàng mới: CK 1%.

- Khách hàng Masterise Homes: CK 2%.

* Chính sách vay ngân hàng:

- Thanh toán 30% vốn tự có đến khi nhận nhà và Ngân hàng Techcombank cho vay 70%.

- Ân hạn gốc lãi từ 24 - 49 tháng.
Ko.
- Hỗ trợ lãi suất 0% sau bàn giao nhà đến 6 tháng.

- Tặng 2 năm phí quản lý.
------------------

* Tiêu chuẩn bàn giao căn hộ Masteri Cosmo Central:

- Cửa chính vào căn hộ trang bị cửa gỗ chống cháy.

- Khóa cửa căn hộ sử dụng thương hiệu Hafele (Đức): Bao gồm các chức năng như mật mã, khóa từ, vân tay, khóa cơ.

- Thiết bị bếp gồm: Tủ bếp trên + dưới, bồn rửa chén, bếp điện từ, máy hút mùi, sử dụng thương hiệu Hafele (Đức).

- Full thiết bị vệ sinh cao cấp và trong toillet trang bị vách ngăn kính cường lực khung Inox.

- Thiết bị điện thương hiệu Schneider Electric (Pháp).

- Máy lạnh Mitsubishi (Nhật Bản).

* Tiện ích nội khu cao cấp chuẩn khu Resort nghỉ dưỡng 5 sao chuẩn Quốc tế.
------------------------------
3) Thông tin tổng quan.
Vị trí: Tọa lạc trung tâm The Global City 117,4ha và MĐXD chỉ 28% còn lại là mảng xanh và tiện ích.
- Chủ đầu tư: Masterise Homes.
- Thiết kế kiến trúc: Foster + Partners.
- Thầu XD: Coteccons.
- Quy mô: 1.4 ha, cao 29 tầng, 2 tầng hầm, 4 tầng Shophouse.
- Số lượng: 900 căn hộ.
- Thời gian bàn giao dự kiến: Quý 3/2028.
------------------
4) Các yếu tố tiềm năng tăng giá.
- Nút giao An Phú: Với tổng mức đầu tư hơn 3.400 tỷ đồng. Quy mô phần đường từ 10 - 12 làn xe, phần hầm chui 4 làn xe hai chiều, các cầu vượt mỗi nhánh 2 làn xe.
- Đường Liên Phường: Vốn đầu tư 3.563 tỷ đồng. Quy mô chiều dài 4,5 km, rộng 40 m với 6 làn xe.
- Metro Bến Thành - Suối Tiên: Sau khi đường Liên Phường đi qua dự án hoàn thiện vào đầu năm 2025, cư dân tại Global City sẽ dễ dàng tiếp cận nhà ga Metro số 1 tại dự án Masteri Thảo Điền chỉ trong vòng 5 phút di chuyển.
- Cao tốc TP. HCM Long Thành Dầu Giây: Nâng cấp mở rộng từ 6 làn xe lên tới 10 làn xe.
------------------
* Liên hệ ngay văn phòng Masteri Homes: 0902 999 *** - Mr Sỹ để được hỗ trợ phân tích bài toán đầu tư hạ tầng.', 'AVAILABLE', 'Masteri Cosmo Central, Phường An Phú, Quận 2, Hồ Chí Minh', 'Phường An Phú', 'Quận 2', 'Hồ Chí Minh', 10.803968, 106.772863, 78.30, NULL, 2, 2, NULL, NULL, 'Hợp đồng mua bán', 7500000000.00, 'VND', NULL, NULL, NULL, NULL, NULL, NULL, '{"balcony_orientation":null,"commercial_subtype":null,"content_sha256":"3ff13a566fd9aaf136e1cded4ef2e2efc46c4a627a2b6d4aed3cd5bd222eb22f","crawled_at":"2026-08-06T07:03:38.335480Z","furniture_status":"Cơ bản","last_seen_at":"2026-08-06T07:03:38.335480Z","listing_type":"SALE","market_insights":{"annual_change_direction":null,"annual_change_percent":null,"history_points":[],"pricing_history_endpoint":null,"pricing_history_endpoint_available":false,"pricing_history_fetched":false,"pricing_history_years":null},"price_per_sqm":95785440,"price_period":"TOTAL","privacy":{"direct_contact_policy":"MASKED_PUBLIC_PHONE_ONLY","free_text_contact_redactions":0},"project":{"name":null,"url":null},"raw_attributes":[{"label":"Khoảng giá","normalized_key":"source_price_per_sqm","normalized_value":7500000000,"raw_value":"7,5 tỷ"},{"label":"Diện tích","normalized_key":"area_sqm","normalized_value":78.3,"raw_value":"78,3 m²"},{"label":"Số phòng ngủ","normalized_key":"bedrooms","normalized_value":2,"raw_value":"2 phòng"},{"label":"Số phòng tắm, vệ sinh","normalized_key":"bathrooms","normalized_value":2,"raw_value":"2 phòng"},{"label":"Mức giá điện","normalized_key":null,"normalized_value":"Thỏa thuận","raw_value":"Thỏa thuận"},{"label":"Pháp lý","normalized_key":"legal_status","normalized_value":"Hợp đồng mua bán","raw_value":"Hợp đồng mua bán"},{"label":"Nội thất","normalized_key":"furniture_status","normalized_value":"Cơ bản","raw_value":"Cơ bản"}],"schema_version":"batdongsan-v1","seller":{"account_type":"BROKER","active_listing_count":68,"avatar_url":"https://file4.batdongsan.com.vn/resize/200x200/2026/05/04/20260504111744-7bc9.