INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('39fe327d-820d-52f0-8163-30ada5027fe6', 'BDS_PR46049237', 'VILLA', 'BT kinh doanh liên Hà, TL422 24m, Hừng Đông 30m, mặt tiền 8m, 25m, giá 1/2 Tây Hồ, Mỹ Đình', 'Gửi quý khách hàng anh chị Nổi bật SHOPHOUSE TIỀM NĂNG BẬC NHẤT VINHOMES WONDER CITY - HĐ-11 Diện tích đất: 128m² DTXD: 374.6m² Hướng: Đông Bắc TCBG: Thô Giá TTS: 25.548 tỷ = Với đơn giá diện tích sử dụng chỉ khoảng ~68tr/m² Giá vay 24 tháng: 29.803 tỷ - Với dòng vốn tự có từ khoảng ~8.8tỷ. Hỗ trợ 2 năm không lãi suất, không trả gốc, không phí trả nợ trước hạn. CHÍNH SÁCH BÁN HÀNG HẤP DẪN Chiết khấu TTS lên đến 7.5% Hỗ trợ lãi suất lên đến 36 tháng Miễn phí dịch vụ 36 tháng khi hoàn thành ký HĐMB đúng hạn. ĐIỂM NỔI BẬT CỦA CĂN HĐ-11 - Hd 05,Hd 83, Hd 99, Tl 422-66, Hd 19-14 Vị trí đẹp trong phân khu, chỉ vài bước chân tới Wellness Park, mang đến không gian sống xanh và nguồn khách hàng ổn định cho hoạt động kinh doanh. Nằm gần Vinschool và Vincom, dễ dàng tiếp cận cộng đồng cư dân đông đúc cũng như lượng khách mua sắm, vui chơi trong tương lai. Tiềm năng gia tăng giá trị lớn khi hệ sinh thái tiện ích của Vinhomes Wonder City hoàn thiện và cư dân về ở đông đúc, đặc biệt với lợi thế nằm gần trục tiện ích trung tâm. Liên hệ em Định VinHomes 0969 693 ***0975 935 ***', 'AVAILABLE', 'HD-05, Đường Hừng Đông, Vinhomes Wonder City, Xã Tân Hội, Huyện Đan Phượng, Hà Nội', 'Xã Tân Hội', 'Huyện Đan Phượng', 'Hà Nội', 21.096520, 105.712100, 145.40, NULL, 6, 4, NULL, NULL, 'Hợp đồng mua bán', 29080000000.00, 'VND', NULL, NULL, NULL, NULL, 8.00, 30.00, '{"balcony_orientation":"Tây Bắc","commercial_subtype":null,"content_sha256":"de6200788ec1e454a4e848c66f275dbdf4135acd33fc217ae7ae9a0029b02ca1","crawled_at":"2026-08-06T07:11:37.258394Z","furniture_status":"Thô","last_seen_at":"2026-08-06T07:11:37.258394Z","listing_type":"SALE","market_insights":{"annual_change_direction":"DOWN","annual_change_percent":-4.3,"history_points":[],"pricing_history_endpoint":"https://batdongsan.com.vn/Origins/CommonData/GetPricingHistory","pricing_history_endpoint_available":true,"pricing_history_fetched":false,"pricing_history_years":1},"price_per_sqm":200000000,"price_period":"TOTAL","privacy":{"direct_contact_policy":"MASKED_PUBLIC_PHONE_ONLY","free_text_contact_redactions":0},"project":{"name":null,"url":null},"raw_attributes":[{"label":"Khoảng giá","normalized_key":"source_price_per_sqm","normalized_value":200000000,"raw_value":"200 triệu/m²"},{"label":"Diện tích","normalized_key":"area_sqm","normalized_value":145.4,"raw_value":"145,4 m²"},{"label":"Số phòng ngủ","normalized_key":"bedrooms","normalized_value":6,"raw_value":"6 phòng"},{"label":"Số phòng tắm, vệ sinh","normalized_key":"bathrooms","normalized_value":4,"raw_value":"4 phòng"},{"label":"Số tầng","normalized_key":"total_floors","normalized_value":4,"raw_value":"4 tầng"},{"label":"Hướng ban công","normalized_key":"balcony_orientation","normalized_value":"Tây Bắc","raw_value":"Tây - Bắc"},{"label":"Mặt tiền","normalized_key":"frontage_m","normalized_value":8.0,"raw_value":"8 m"},{"label":"Đường vào","normalized_key":"road_width_m","normalized_value":30.0,"raw_value":"30 m"},{"label":"Pháp lý","normalized_key":"legal_status","normalized_value":"Hợp đồng mua bán","raw_value":"Hợp đồng mua bán"},{"label":"Nội thất","normalized_key":"furniture_status","normalized_value":"Thô","raw_value":"Thô"}],"schema_version":"batdongsan-v1","seller":{"account_type":"BROKER","active_listing_count":8,"avatar_url":"https://file4.batdongsan.com.vn/resize/255x180/2026/07/07/20260707120104-58f0.jpg","display_name":"Hoàng Văn Định","has_broker_badge":false,"has_chat":false,"has_zalo":false,"is_professi