INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('c07cd524-5776-5139-a44b-ab50fde0c196', 'BDS_PR46125904', 'APARTMENT', 'Cắt lỗ - Căn hộ 2N, 1N + STU, 3N Vinhomes Ocean Park - Sổ đỏ - Nhà mới - Giá chỉ từ 1,6T', 'Chính chủ cần tiền gửi bán gấp căn hộ 2N, 1N + Studio và 3N - Từ nguyên bản đến full nội thất - nhà mới chưa ở - sẵn sổ giao dịch ngay.

Liên hệ ĐT/Zalo 24/7: 0986 021 ***.

I. Các phân khu đã bàn giao nhà, ở ngay gồm:

- Phân khu Sapphire S1 và S2 (phân khu trung cấp, giá thuê giá rẻ, cư dân về ở sớm nhất, tiện ích đầy đủ).
- Phân khu cao cấp Beverly - Zurich mới bàn giao nhà, nhà mới có nhiều sự lựa chọn, dv tiện ích cao cấp.
- Phân khu cao cấp Ruby - The Zenpark (có bể bơi bốn mùa Miễn phí, khu vui chơi vườn Nhật, hồ cá Koi, tận hưởng không gian nghỉ dưỡng theo phong cách Nhật Bản).
- Phân khu Pavilion - phong cách ốc đảo nghỉ dưỡng Singapore, phân khu hiếm có có 2 tầng hầm để xe oto và kế bên các tòa nhà dịch vụ tiện ích cao cấp).
- Phân khu Zurich - phân khu căn hộ cao cấp phong cách Thụy Sĩ hiện đại, nằm tại vị trí trung tâm của đại đô thị Ocean Park, đã bàn giao nhà ở ngay.

Liên hệ ĐT/Zalo 24/7: 0986 021 ***.

+ Giá bán nhanh cập nhật:

- Căn Studio: Giá 1,6 tỷ - 2,2 tỷ.
- Căn 1N + 1: Giá 2,550 tỷ - 2,8 tỷ.
- Căn 2N + 1WC: Giá 3 tỷ - 3,2 tỷ.
- Căn 2N + 2WC: Giá 3,45 tỷ - 3,7 tỷ.
- Căn 3N + 2WC: 4,2 tỷ - 5,2 tỷ.

- Đa dạng phong cách thiết kế.
- Miễn phí tư vấn, dẫn đi xem nhà.
- Hỗ trợ xem nhà 24/7h.
