INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('c51ccada-ce5d-550c-b1c0-38b90fcf4d5c', 'BDS_PR45384917', 'APARTMENT', 'Giỏ hàng mới || 2PN, 3PN, office, CĐT mở bán (bàn giao hoàn thiện) || Thanh toán 15% kí HĐMB', 'Tổng quan dự án:
The Peak Garden Q7 - liền kề KĐT Phú Mỹ Hưng đối diện nhà ga Metro Tân Mỹ.
Mặt tiền Nguyễn Lương Bằng - Phạm Hữu Lầu, P. Tân Mỹ, Quận 7 (View trực diện sông Sài Gòn).
52.000m² | 110 căn villa & 2 tháp căn hộ cao 26 tầng | 2 tầng hầm.

Loại hình sản phẩm:
Offictel: 35m² - 70 m².
- 2 PN: 65m² - 73m².
- 3 PN: 85m² - 101m².
- Shophose (01): 50m² - 80m².
Duplex Pen: 150 m² - 210m².

Tầng 1 - 4: Trung tâm thương mại, Shophouse, Nhà trẻ, Sinh hoạt cộng đồng.
Tầng 5: Gym, BBQ sân vườn trên không.

- Bàn giao hoàn thiện cơ bản cho căn hộ.

Phương thức thanh toán siêu nhẹ linh hoạt.
- Đặt cọc chỉ 50 triệu.
- Ký HĐMB thanh toán 15%.
- Giai đoạn xây dựng (Đợt 3 - 6): Mỗi đợt chỉ 5% khi đổ bê tông sàn các tầng 12, 15, 18, 21.
- Cất nóc (tầng 27) thanh toán 15%.
- Nhận nhà thanh toán 45%.
- Nhận sổ hồng chỉ 5% cuối cùng.

Lịch thanh toán được giãn tối đa giảm áp lực tài chính, dễ dàng sở hữu.

Thanh toán theo tiến độ vay: Chiết khấu 3% vào giá bán (trước VAT).
- Đặt cọc chỉ 50 triệu.
- Ký HĐMB thanh toán 30%.
- Giai đoạn xây dựng khi đổ bê tông sàn các tầng 12: 40%.
- Nhận nhà thanh toán 25%.
- Nhận sổ hồng chỉ 5% cuối cùng.

Ưu đãi thanh toán nhanh cho khách sẵn vốn.
- Thanh toán 95% giá trị căn hộ.
- Nhận ngay chiết khấu 6% tối ưu lợi nhuận đầu tư.

Đã có GPXD, Ký HĐMB, đang thi công rầm rộ tầng 9 bởi Hoà Bình Cons,
Mở bán chính thức: Dự kiến T05/2026 hiện tại đang nhận booking 50.000.000/suất.
Dự kiến bàn giao nhà: Đầu 8.
Đ: "Hàng hiếm" cho khách hàng tìm kiếm căn hộ mới, pháp lý chuẩn chỉnh tại Q7.
Số lượng sản phẩm khá ít:
+ Khoảng 200 căn hộ.
+ 80 căn TMDV.
+ Shophouse, Duplex.
Timeline triển khai:
- Dự kiến mở bán T05/2026.
Nhận booking: 50 triệu (hoàn lại).

Đây là sản phẩm chất lượng, pháp lý đầy đủ, giá trị đầu tư và an cư bền vững.
