INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('4fb00392-7b86-5427-84c0-baf18fe257dd', 'BDS_PR46113055', 'APARTMENT', 'Siêu hot: Bán nhanh căn 2PN+ S303, 64m², 4 tỷ 150 căn góc view hồ, thoáng nhất Smart City', 'Em cần bán nhanh căn hộ 2PN+1 (phần cộng có thể làm thêm thành 1 phòng ngủ nhỏ cho gia đình có nhu cầu tổng 3 phòng ngủ), tòa S303 tại dự án Vinhomes Smart City phân khu The Sapphire.

- Diện tích thông thủy: 64 m².
- Căn hộ đã có sổ đỏ, pháp lí rõ ràng.
- Hướng ban công: Đông Nam.
- Căn hộ để lại full nội thất mới như ảnh.
- Tầng 18.
- Căn góc view 2 mặt thoáng, mát mẻ.
- Hướng ban công mát mẻ view với tầm view thoáng nhìn ra bể bơi.
- Vị trí: Tọa lạc tại trung tâm dự án, giao thông và đi lại thuận tiện, gần trường học, công viên trung tâm với nhiều dịch vụ tiện ích. Cạnh nhà để xe nổi Parking Zone 3,4 thuận tiện di chuyển đi lại.
- Giá bán: 4 tỷ 150.
- Có ra lộc thêm cho khách thiện chí!
