INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('ae3034fb-8c1c-5eef-a53a-cc8625628f16', 'BDS_PR46120898', 'APARTMENT', 'Bán gấp căn hộ 2PN, 75m2 tại The Emerald River Park, 3,6 tỷ', 'Căn hộ chung cư The Emerald River Park, Đường Bờ Bao Sông Sài Gòn, Phường Lái Thiêu, Hồ Chí Minh, với thiết kế hiện đại và tiện nghi đầy đủ, mang đến không gian sống lý tưởng cho cư dân.

- Diện tích: 75m².
- Số phòng ngủ: 2PN.
- Số toilet: 2WC.
- Giá bán: 3,6 tỷ VND.

Căn hộ nằm trong khu vực có phong thủy tốt, tạo cảm giác thoải mái và an lành cho gia đình. Pháp lý đầy đủ, đảm bảo an toàn cho người sở hữu. Với vị trí thuận lợi, căn hộ này hứa hẹn mang lại một cuộc sống tiện nghi và hiện đại.

