INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('6e50639a-a919-5b02-a084-089b68fa808e', 'BDS_PR46120396', 'APARTMENT', 'The Global City chỉ 2.6 tỉ sở hữu ngay căn 2 phòng ngủ rộng 78m2, hỗ trợ vay 48 tháng không gốc lãi', 'The Global City là căn hộ cao cấp do CĐT Masterise Homes phát triển, được thiết kế bởi đơn vị thiết kế danh tiếng Foster + Partners và được Techcombank hỗ trợ vay lên đến 48 tháng không gốc lãi.

Em Đông còn vài căn suất nội bộ The Global đợt 1 với mức giá cực kỳ ưu đãi như sau:
* Căn 1PN:
+ Căn 1PN diện tích 55m², giá chỉ 6 tỷ đã bao gồm VAT và PBT. (Tặng kèm 2 năm PQL).
* Căn 2PN:
+ Căn 2PN diện tích 78m² giá chỉ 8,5 tỷ đã bao gồm VAT và PBT. (Tặng kèm 2 năm PQL).
* Căn 3PN:
+ Căn 3PN diện tích 100m², giá chỉ 11,3 tỷ đã bao gồm VAT và PBT. (Tặng kèm 2 năm PQL).
* Căn 4PN :
+ Căn 4PN diện tích 115m², giá chỉ 16 tỷ đã bao gồm VAT và PBT. (Tặng kèm 2 năm PQL).

Hotline liên hệ : 0903 899 *** Mr Đông GDKD.

I,VỀ KẾT NỐI.
***The Global City với diện tích lên đến 117,4 Hecta,là một trong 4 mảnh ghép quan trọng nhất của đại đô thị Nam Rạch Chiếc,là nơi sở hữu vị trí vàng đắc địa của khu Đông TP.HCM khi chỉ :

+5 phút kết nối đến sân vận động hoa Sen Nam Rạch Chiếc,5 phút đi xe về Thảo Điền và 10p kết nối đến trung tâm quận 1 cũ.

+10p để kết nối về đại đô thị Thủ Thiêm thông qua nút giao An Phú đang được hoàn thiện.

+Trong bán kính 5km có thể kết nối với 06 cụm siêu thị và trung tâm thương mại,08 trường quốc tế và 05 bệnh viện.

II,VỀ TIỆN ÍCH.
***The Global City cũng là nơi phức hợp đầy đủ tất cả các tiện ích nổi bật Đông Nam Á,tiêu biểu như :

+Sân khấu nhạc nước dài và đẹp Đông Nam Á..

+Sở hữu 2 trong 4 bến Du Thuyền và Taxi nước của TP.HCM.

+Trung tâm thương mại lớn nhất Việt Nam (123.000m²) do tập đoàn Lotte đầu tư phát triển và vận hành.

+Sở hữu 04 cụm trường học quốc tế,nổi bật nhất trong số đó là trường quốc tế danh giá đến từ Anh quốc King''s College Wimbledon .

+Sở hữu 02 cụm bệnh viện quốc tế.....

+Các tiện ích khác như nhà hàng 5 sao,trường đua xe,trường đua ngựa......

Không chỉ vậy, dự án còn sở hữu hơn 100 tiện ích ngoại khu của mỗi phân khu,vậy nên The Global City được mệnh danh là ông vua tiện ích của BĐS trung tâm TP.HCM.

***Ngoài ra e Đông cũng nắm giỏ hàng khác thuộc The Global City như phân khu nhà phố kinh doanh Soho,biệt thự Sola cũng như giỏ hàng phân khu cao tầng CT5, CT4, CT3 với mức giá tốt và chiết khấu cao nhất từ CĐT.

