INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('eec128d6-5dd8-533e-b846-3b8169626754', 'BDS_PR45385749', 'APARTMENT', 'Suất ngoại giao chiết khấu 18% căn hộ Global City CT3-CT4-CT5 chọn căn ưu tiên. LH trực tiếp CĐT', 'Chính thức nhận booking 100 triệu/suất (có hoàn lại) ~ khách booking sớm được tặng nhiều chính sách hấp dẫn trực tiếp từ Masteri Homes.
1) Loại hình căn hộ.
- Căn 1PN: 53m² - Giá: 6,5 tỷ ~ 6,9 tỷ.
- Căn 2PN: 67m², 72m², 76m², 81m² - Giá: 7,7 tỷ ~ 8,5 tỷ.
- Căn 3PN: 90m², 130m² - Giá: 11,5 tỷ.
- Căn 4PN: 135m², 145m² - Giá: 17 tỷ ~ 19 tỷ.
- Căn hộ Duplex 85m², 92m² - Giá: 9 tỷ ~ 10,2 tỷ.
* Liên hệ ngay văn phòng Masteri Homes: 0902 919 *** Mr Nghĩa để được hỗ trợ lấy căn giá tốt trực tiếp từ CĐT.

2) Chính sách bán hàng.
- Chiết khấu lên tới 18%.
- Thanh toán 20% nhận nhà và ngân hàng hỗ trợ vay tối đa 80% giá trị căn hộ.
- Hỗ trợ 0% lãi suất 24 tháng và ân hạn gốc tới 36 tháng.
* Liên hệ ngay văn phòng Masteri Homes: 0902 919 *** Mr Nghĩa để được hỗ trợ chính sách bán hàng trực tiếp từ CĐT.

3) Thông tin tổng quan.
Vị trí: Tọa lạc trung tâm The Global City 117,4ha và MĐXD chỉ 28% còn lại là mảng xanh và tiện ích.
- Chủ đầu tư: Masterise Homes.
- Thiết kế kiến trúc: Foster + Partners.
- Quy mô: 1,4 ha, cao 27 tầng, 2 tầng hầm, 4 tầng Shophouse.
- Số lượng: 808 Căn hộ.
- Thời gian bàn giao dự kiến: Quý 3/2027.
* Liên hệ ngay văn phòng Masteri Homes: 0902 919 *** Mr Nghĩa để được hỗ trợ xem thực tế sa bàn nhà mẫu.

4) Các yếu tố tiềm năng tăng giá.
+ Nút giao An Phú: Với tổng mức đầu tư hơn 3.400 tỷ đồng. Quy mô phần đường từ 10 - 12 làn xe, phần hầm chui 4 làn xe hai chiều, các cầu vượt mỗi nhánh 2 làn xe.
+ Đường Liên Phường: Vốn đầu tư 3.563 tỷ đồng. Quy mô chiều dài 4,5 km, rộng 40 m với 6 làn xe.
+ Metro Bến Thành - Suối Tiên: Sau khi đường Liên Phường đi qua dự án hoàn thiện vào đầu năm 2025, cư dân tại Global City sẽ dễ dàng tiếp cận nhà ga metro tốt tại dự án Masteri Thảo Điền chỉ trong vòng 5 phút di chuyển.
+ Cao tốc TP. HCM Long Thành Dầu Giây: Nâng cấp mở rộng từ 6 làn xe lên tới 10 làn xe.
* Liên hệ ngay văn phòng Masteri Homes: 0902 919 *** - Mr Nghĩa để được hỗ trợ phân tích bài toán đầu tư hạ tầng.', 'AVAILABLE', 'The Global City, Phường An Phú, Quận 2, Hồ Chí Minh', 'Phường An Phú', 'Quận 2', 'Hồ Chí Minh', 10.802472, 106.776843, 76.00, NULL, 2, 2, NULL, NULL, 'Hợp đồng mua bán', 7800000000.00, 'VND', NULL, NULL, NULL, NULL, NULL, NULL, '{"balcony_orientation":null,"commercial_subtype":null,"content_sha256":"5309f13d3325c74b9fffca707b1544793bfa0307d783875582fe674e6bd178a9","crawled_at":"2026-08-06T07:05:21.459056Z","furniture_status":null,"last_seen_at":"2026-08-06T07:05:21.459056Z","listing_type":"SALE","market_insights":{"annual_change_direction":"DOWN","annual_change_percent":-17.4,"history_points":[],"pricing_history_endpoint":"https://batdongsan.com.vn/Origins/CommonData/GetPricingHistory","pricing_history_endpoint_available":true,"pricing_history_fetched":false,"pricing_history_years":1},"price_per_sqm":102631578,"price_period":"TOTAL","privacy":{"direct_contact_policy":"MASKED_PUBLIC_PHONE_ONLY","free_text_contact_redactions":0},"project":{"name":null,"url":null},"raw_attributes":[{"label":"Khoảng giá","normalized_key":"source_price_per_sqm","normalized_value":7800000000,"raw_value":"7,8 tỷ"},{"label":"Diện tích","normalized_key":"area_sqm","normalized_value":76.0,"raw_value":"76 m²"},{"label":"Số phòng ngủ","normalized_key":"bedrooms","normalized_value":2,"raw_value":"2 phòng"},{"label":"Số phòng tắm, vệ sinh","normalized_key":"bathrooms","normalized_value":2,"raw_value":"2 phòng"},{"label":"Mức giá điện","normalized_key":null,"normalized_value":"Thỏa thuận","raw_value":"Thỏa thuận"},{"label":"Pháp lý","normalized_key":"legal_status","normalized_value":"Hợp đồng mua bán","raw_value":"Hợp đồng mua bán"}],"schema_version":"batdongsan-v1","seller":{"account_type":"UNKNOWN","active_listing_count":null,"avatar_url":"https://staticfile.batdongsan.com.vn/images/avatar/no-image-default.png","display_name":"Trần Minh Nghĩa","has_broker_badge":false