INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, usable_area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, parcel_number, map_sheet_number, land_use_purpose, land_use_term, frontage_m, road_width_m, features, published_at) VALUES ('33419c63-f41e-5949-9e4e-adc42449c72e', 'BDS_PR46112092', 'VILLA', 'Booking PK Rừng Phượng thanh toán chỉ 590tr nhận nhà, NH hỗ trợ 0% LS, ân hạn gốc 24 tháng. CK 13%', 'Rừng Phượng phân khu giáo dục biểu tượng tại Eco Retreat. Trong một khu đô thị, giá trị nhất không chỉ nằm ở vị trí đẹp, mà còn ở môi trường sống dành cho thế hệ tương lai. Rừng Phượng được quy hoạch là phân khu giáo dục của Eco Retreat, tọa lạc trên Đại lộ trung tâm 40m, liền kề Trường Quốc tế, công viên và chuỗi tiện ích nghỉ dưỡng chuẩn resort. Đây là nơi trẻ em được lớn lên giữa thiên nhiên, gia đình tận hưởng cuộc sống an yên và nhà đầu tư sở hữu một tài sản có giá trị gia tăng bền vững.
THÔNG TIN MỞ BÁN ĐỢT 1
Booking: 100 triệu/suất
Giá dự kiến từ 5,9 tỷ/căn (đã gồm VAT & KPBT, chưa trừ chiết khấu)
Chỉ 325 sản phẩm giới hạn, gồm:
182 Nhà phố Vườn
* Diện tích: 80 174,6m2
* Xây dựng: 3 tầng + tum
* Thiết kế hướng đến cuộc sống xanh, kết nối công viên và không gian thiên nhiên.
85 Nhà phố Đại lộ
* Diện tích: 144 255,9m2
* Nằm trên trục Đại lộ 40m
* Phù hợp an cư kết hợp kinh doanh, khai thác thương mại và cho thuê.
52 Biệt thự Song lập
* Diện tích: 162 270,7m2
* Thiết kế rộng rãi, riêng tư, dành cho gia đình đa thế hệ.
06 Biệt thự Đơn lập
* Diện tích: 216 369,3m2
* Sản phẩm giới hạn, vị trí đẹp phân khu, tôn lên đẳng cấp của chủ sở hữu.
Rừng Phượng không chỉ là nơi để ở, mà là nơi kiến tạo một chuẩn sống mới: con trẻ được nuôi dưỡng trong môi trường giáo dục chất lượng, gia đình tận hưởng thiên nhiên mỗi ngày và tài sản được bồi đắp giá trị theo thời gian.
Một phân khu đẹp để an cư. Một vị trí hiếm để đầu tư. Một tài sản xứng đáng để truyền lại cho thế hệ mai sau.
